//! One-dimensional bin packing with known optima, used to demonstrate
//! program evolution.
//!
//! Instances are generated by cutting `k` bins of capacity `C` into random
//! integer pieces that fill each bin exactly, then shuffling the pieces:
//! the optimum is therefore exactly `k` bins (the volume bound `ΣsᵢC⁻¹ = k`
//! is attained).  The scorer, written in Rust and independent of the
//! candidate, checks that every item is assigned to a bin index and that no
//! bin overflows, then reports `bins_used / k` (1.0 = optimal).

use crate::program::{Program, ProgramTask, SandboxOutput, SealedInstances, TaskScore};
use rand::seq::SliceRandom;
use rand::{Rng, SeedableRng};
use rand_chacha::ChaCha8Rng;

/// Score assigned to an instance whose solution is missing or infeasible.
pub const INFEASIBLE_RATIO: f64 = 3.0;

/// `n_instances` instances of `bins` exactly-filled bins of `capacity`.
pub fn generate(n_instances: usize, bins: usize, capacity: i64, seed: u64) -> serde_json::Value {
    let mut rng = ChaCha8Rng::seed_from_u64(seed);
    let mut out = vec![];
    for _ in 0..n_instances {
        let mut items: Vec<i64> = vec![];
        for _ in 0..bins {
            let mut left = capacity;
            while left > 0 {
                let piece = if left <= capacity / 10 {
                    left
                } else {
                    rng.gen_range(capacity / 10..=left.min(capacity * 6 / 10))
                };
                items.push(piece);
                left -= piece;
            }
        }
        items.shuffle(&mut rng);
        out.push(serde_json::json!({"items": items, "capacity": capacity, "__optimum": bins}));
    }
    // the optimum is kept on the Rust side only: strip it from what the candidate sees
    serde_json::Value::Array(out)
}

/// First-fit in the given order (the seed program).
pub const SEED_FIRST_FIT: &str = r#"def pack(items, capacity):
    order = list(range(len(items)))
    bins = []
    assign = [0] * len(items)
    for i in order:
        placed = False
        for b in range(len(bins)):
            if bins[b] >= items[i]:
                bins[b] -= items[i]
                assign[i] = b
                placed = True
                break
        if not placed:
            bins.append(capacity - items[i])
            assign[i] = len(bins) - 1
    return assign
"#;

/// Snippet bank for the syntactic mutator (generic list manipulations, not
/// a solution: the search has to find where and which to insert).
pub fn snippets() -> Vec<String> {
    vec![
        "order.sort(key=lambda j: -items[j])".into(),
        "order.sort(key=lambda j: items[j])".into(),
        "order.reverse()".into(),
        "order = order[1:] + order[:1]".into(),
        "bins.sort()".into(),
        "placed = False".into(),
    ]
}

pub struct BinPackingTask {
    train: SealedInstances,
    held_out: SealedInstances,
    optima_train: Vec<i64>,
    optima_held: Vec<i64>,
}

fn split_optimum(v: serde_json::Value) -> (serde_json::Value, Vec<i64>) {
    let mut optima = vec![];
    let arr: Vec<serde_json::Value> = v
        .as_array()
        .cloned()
        .unwrap_or_default()
        .into_iter()
        .map(|mut inst| {
            optima.push(inst["__optimum"].as_i64().unwrap_or(1));
            inst.as_object_mut().map(|o| o.remove("__optimum"));
            inst
        })
        .collect();
    (serde_json::Value::Array(arr), optima)
}

impl BinPackingTask {
    pub fn new(train_instances: usize, held_out_instances: usize, bins: usize, seed: u64) -> Self {
        let (t, ot) = split_optimum(generate(train_instances, bins, 100, seed));
        let (h, oh) = split_optimum(generate(
            held_out_instances,
            bins,
            100,
            seed.wrapping_add(10_007),
        ));
        Self {
            train: SealedInstances::seal("binpacking-train", t),
            held_out: SealedInstances::seal("binpacking-held-out", h),
            optima_train: ot,
            optima_held: oh,
        }
    }

    pub fn seed_program() -> Program {
        Program::new(SEED_FIRST_FIT, None, "seed: first-fit")
    }

    fn optima(&self, set: &SealedInstances) -> &[i64] {
        if set.hash == self.train.hash {
            &self.optima_train
        } else {
            &self.optima_held
        }
    }
}

/// Independent feasibility check and bin count.
pub fn bins_used(items: &[i64], capacity: i64, sol: &serde_json::Value) -> Result<i64, String> {
    let a = sol.as_array().ok_or("solution is not a list")?;
    if a.len() != items.len() {
        return Err(format!(
            "solution has {} entries for {} items",
            a.len(),
            items.len()
        ));
    }
    let mut loads: std::collections::BTreeMap<i64, i64> = Default::default();
    for (s, v) in items.iter().zip(a) {
        let b = v.as_i64().ok_or("bin index is not an integer")?;
        if b < 0 {
            return Err("negative bin index".into());
        }
        *loads.entry(b).or_default() += s;
    }
    if let Some((b, l)) = loads.iter().find(|(_, l)| **l > capacity) {
        return Err(format!("bin {b} overloaded ({l} > {capacity})"));
    }
    Ok(loads.len() as i64)
}

impl ProgramTask for BinPackingTask {
    fn name(&self) -> &str {
        "bin-packing"
    }
    fn entry_point(&self) -> &str {
        "pack"
    }
    fn description(&self) -> &str {
        "pack(items: list[int], capacity: int) -> list[int]: return, for each item, the index of the bin it goes to, minimising the number of bins; no bin may exceed capacity."
    }
    fn train(&self) -> &SealedInstances {
        &self.train
    }
    fn held_out(&self) -> &SealedInstances {
        &self.held_out
    }
    fn score(&self, set: &SealedInstances, out: &SandboxOutput) -> TaskScore {
        let optima = self.optima(set);
        let insts = set.instances.as_array().cloned().unwrap_or_default();
        let mut per = vec![];
        let mut failures = 0;
        let mut messages = vec![];
        for (k, inst) in insts.iter().enumerate() {
            let items: Vec<i64> = inst["items"]
                .as_array()
                .map(|a| a.iter().filter_map(|v| v.as_i64()).collect())
                .unwrap_or_default();
            let cap = inst["capacity"].as_i64().unwrap_or(0);
            let sol = out
                .solutions
                .get(k)
                .cloned()
                .unwrap_or(serde_json::Value::Null);
            match bins_used(&items, cap, &sol) {
                Ok(n) => per.push(n as f64 / optima[k] as f64),
                Err(e) => {
                    failures += 1;
                    per.push(INFEASIBLE_RATIO);
                    let why = out.errors.get(k).cloned().flatten().unwrap_or(e);
                    if messages.len() < 5 {
                        messages.push(why);
                    }
                }
            }
        }
        let score = per.iter().sum::<f64>() / per.len().max(1) as f64;
        TaskScore {
            score,
            failures,
            per_instance: per,
            messages,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn instances_have_exact_optimum_and_scorer_rejects_overload() {
        let v = generate(3, 5, 100, 1);
        for inst in v.as_array().unwrap() {
            let s: i64 = inst["items"]
                .as_array()
                .unwrap()
                .iter()
                .map(|x| x.as_i64().unwrap())
                .sum();
            assert_eq!(s, 500);
        }
        assert_eq!(
            bins_used(&[60, 50], 100, &serde_json::json!([0, 0])).unwrap_err(),
            "bin 0 overloaded (110 > 100)"
        );
        assert_eq!(
            bins_used(&[60, 40], 100, &serde_json::json!([0, 0])).unwrap(),
            1
        );
        assert!(bins_used(&[60, 40], 100, &serde_json::json!([0])).is_err());
    }
}
